critic.parse.enabled.expression:
match block.get("enabled") {
        None => {}
        Some(value) => match value.as_bool() {
            Some(enabled) => candidate.enabled = Some(enabled),
            None => rejected.push(RejectedSibling::new(setting, value.to_string())),
        },
    }

