client.readExternalIncludePaths.expression:
{
  const inspected = config.inspect?.('externalIncludePaths') as
    | {
        globalValue?: unknown;
      }
    | undefined;

  if (!inspected || inspected.globalValue === undefined) {
    return undefined;
  }

  if (!Array.isArray(inspected.globalValue)) {
    return undefined;
  }

  return inspected.globalValue.filter((value): value is string => typeof value === 'string');
}

client.buildWorkspaceConfigurationPayloa.expression:
{
  const includePathsExplicit = hasExplicitOverride(config, 'includePaths');
  const externalIncludePaths = readExternalIncludePaths(config);

  if (!includePathsExplicit && externalIncludePaths === undefined) {
    return undefined;
  }

  const workspace: Record<string, unknown> = {};
  if (includePathsExplicit) {
    workspace.includePaths = readIncludePaths(config);
  }
  if (externalIncludePaths !== undefined) {
    workspace.externalIncludePaths = externalIncludePaths;
  }

  return { workspace };
}

client.buildUserAiCompletionConfiguratio.expression:
{
  const enabled = readMachineScopedBoolean(config, 'aiCompletion.enabled', false);
  const streamingEnabled = readMachineScopedBoolean(config, 'aiCompletion.streaming.enabled', true);

  return {
    settings: {
      perl: {
        aiCompletion: {
          enabled,
          streaming: { enabled: streamingEnabled },
        },
      },
    },
  };
}

client.buildLanguageClientConfigurationP.expression:
{
  const config = vscode.workspace.getConfiguration('perl-lsp', documentUri);
  const perl: Record<string, unknown> = {};
  const workspace = buildWorkspaceConfigurationPayload(config);
  if (workspace) {
    Object.assign(perl, workspace);
  }
  const critic = buildCriticSettings(documentUri);
  if (critic) {
    Object.assign(perl, critic);
  }

  return { settings: { perl } };
}

client.buildCriticSettings.expression:
{
  const config = getPerlCriticConfiguration(documentUri);
  const critic = getNativeCriticSyncSettings(config, severityOverride);
  const perlcritic = getLegacyPerlCriticSyncSettings(config);
  const perl: Record<string, unknown> = {};

  if (Object.keys(critic).length > 0) {
    perl.critic = critic;
  }
  if (Object.keys(perlcritic).length > 0) {
    perl.perlcritic = perlcritic;
  }

  return Object.keys(perl).length > 0 ? perl : undefined;
}

critic.context.read.expression:
{
            let cfg = server.config.lock();
            (
                cfg.perlcritic_enabled,
                cfg.perlcritic_severity,
                cfg.perlcritic_profile.clone(),
                cfg.critic_engine,
                cfg.native_critic_profile.clone(),
                cfg.native_critic_include.clone(),
                cfg.native_critic_exclude.clone(),
                AcceptedCriticSnapshot::capture(&cfg, root_key.as_deref()),
            )
        }

workspace.project.expression:
{
        let mut rejected = Vec::new();
        let mut skip_include_paths = false;
        if !self.perl.include_paths.is_empty() {
            // Fail closed: if the workspace root itself cannot be canonicalized
            // there is nothing to validate containment against, so no entry can
            // be trusted. Detected once here rather than inferred per-entry, so
            // the reported reason names the actual cause instead of blaming
            // each path for "escaping" a root that could not be read.
            if let Err(err) = std::fs::canonicalize(workspace_root) {
                // The failure belongs to the workspace root, not to any single
                // entry, so record it once instead of repeating an identical
                // warning per configured path.
                rejected.push(RejectedIncludePath {
                    entry: workspace_root.display().to_string(),
                    reason: RejectedIncludePathReason::WorkspaceRootUnavailable(err.to_string()),
                });
                // Fail closed for include roots: entries are dropped, not merely
                // reported, since leaving a previously-set list in place would
                // let an unvalidated path stay live.
                //
                // Scoped deliberately: this is a path-validation failure, not a
                // failure of the whole project config, so discovery extensions,
                // skip lists and the perl5lib settings below still apply.
                config.include_paths.clear();
                skip_include_paths = true;
            }
            let mut valid = Vec::with_capacity(self.perl.include_paths.len());
            for entry in self.perl.include_paths.iter().filter(|_| !skip_include_paths) {
                let candidate = Path::new(entry);
                if candidate.is_absolute() {
                    rejected.push(RejectedIncludePath {
                        entry: entry.clone(),
                        reason: RejectedIncludePathReason::Absolute,
                    });
                    continue;
                }
                if let Err(err) = validate_workspace_path(candidate, workspace_root) {
                    rejected.push(RejectedIncludePath {
                        entry: entry.clone(),
                        reason: RejectedIncludePathReason::from_path_error(&err),
                    });
                    continue;
                }
                valid.push(entry.clone());
            }
            if !skip_include_paths {
                // Project-file configuration replaces the list; drop detector
                // ownership for the same reason as the client-settings channel
                // (#13640).
                config.detected_dependency_include_paths.clear();
                config.include_paths = valid;
            }
        }
        if !self.perl.discovery_extensions.is_empty() {
            config.discovery_extra_extensions =
                normalize_string_list(&self.perl.discovery_extensions);
        }
        if !self.perl.discovery_skipped_dirs.is_empty() {
            config.discovery_extra_skipped_dirs =
                normalize_string_list(&self.perl.discovery_skipped_dirs);
        }
        if let Some(use_p5l) = self.perl.use_perl5lib {
            config.use_perl5lib = use_p5l;
        }
        if let Some(ref prec) = self.perl.perl5lib_precedence {
            config.perl5lib_precedence = prec.clone();
        }
        rejected
    }

critic.project.expression:
{
        let mut candidate = Self {
            enabled: diagnostics.perlcritic,
            severity: diagnostics.perlcritic_severity.map(|severity| {
                let clamped = severity.clamp(1, 5);
                if clamped != severity {
                    tracing::warn!(
                        target: "perl_lsp::config",
                        setting = "diagnostics.perlcritic_severity",
                        value = severity,
                        valid_range = "1-5",
                        "perlcritic_severity out of range; clamped to {}",
                        clamped,
                    );
                }
                clamped
            }),
            ..Self::default()
        };
        let mut rejected: Vec<RejectedSibling> = Vec::new();

        if let Some(engine) = &critic.engine {
            match crate::config::parse_critic_engine(engine) {
                Some(parsed) => {
                    if parsed == CriticEngine::Legacy {
                        tracing::warn!(
                            target: "perl_lsp::config",
                            setting = "critic.engine",
                            value = %engine,
                            "deprecated critic.engine in .perl-lsp.toml selects the \
                             external compatibility path only; it cannot construct a \
                             product runtime engine state (#8253), migration owned by #9072",
                        );
                    }
                    candidate.engine_raw = Some(parsed);
                }
                None => rejected.push(RejectedSibling::new("critic.engine", engine)),
            }
        }
        if let Some(profile) = &critic.profile {
            match NativeCriticProfile::parse(profile) {
                Some(parsed) => candidate.profile = Some(parsed),
                None => rejected.push(RejectedSibling::new("critic.profile", profile)),
            }
        }
        candidate.include = critic.include.as_ref().map(|ids| {
            let normalized = normalize_string_list(ids);
            warn_unknown_rule_ids(CriticRuleIdSource::ProjectFile, "critic.include", &normalized);
            normalized
        });
        candidate.exclude = critic.exclude.as_ref().map(|ids| {
            let normalized = normalize_string_list(ids);
            warn_unknown_rule_ids(CriticRuleIdSource::ProjectFile, "critic.exclude", &normalized);
            normalized
        });

        finish_candidate(candidate, rejected)
    }

client.hasExplicitOverride.expression:
{
  const value = config.inspect?.(key) as
    | {
        globalValue?: unknown;
        workspaceValue?: unknown;
        workspaceFolderValue?: unknown;
        globalLanguageValue?: unknown;
        workspaceLanguageValue?: unknown;
        workspaceFolderLanguageValue?: unknown;
      }
    | undefined;

  return Boolean(
    value &&
    (value.globalValue !== undefined ||
      value.workspaceValue !== undefined ||
      value.workspaceFolderValue !== undefined ||
      value.globalLanguageValue !== undefined ||
      value.workspaceLanguageValue !== undefined ||
      value.workspaceFolderLanguageValue !== undefined),
  );
}

client.getPerlCriticConfiguration.expression:
{
  const scope: { uri?: vscode.Uri; languageId: string } = documentUri
    ? { uri: documentUri, languageId: 'perl' }
    : { languageId: 'perl' };
  return vscode.workspace.getConfiguration('perl-lsp', scope);
}

client.pickExplicit.expression:
{
  const settings: Partial<T> = {};

  for (const spec of specs) {
    if (hasExplicitOverride(config, spec.key)) {
      settings[spec.property] = config.get(spec.key, spec.defaultValue) as T[typeof spec.property];
    }
  }

  return settings;
}

client.getNativeCriticSyncSettings.expression:
{
  const settings = pickExplicit(config, NATIVE_CRITIC_SPECS);

  if (severityOverride !== undefined) {
    settings.severity = severityOverride;
  }

  return settings;
}

client.readIncludePaths.expression:
{
  const configured = config.get<unknown>('includePaths', [...DEFAULT_INCLUDE_PATHS]);
  if (!Array.isArray(configured)) {
    return [...DEFAULT_INCLUDE_PATHS];
  }

  return configured.filter((value): value is string => typeof value === 'string');
}
